s = open('24.txt').readline().strip()
cnt = {}
for i in range(len(s) - 1):
    if s[i] == 'A':
        cnt[s[i + 1]] = cnt.get(s[i + 1], 0) + 1
best = max(cnt.values())
print(min(c for c in cnt if cnt[c] == best))

